From 40dce0416689fed5816d795a619d8253a8a5126b Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 10:01:33 +0100
Subject: [PATCH] applets/weather: retry soon after a failed forecast update

A failed update counted as fresh data, so if the network wasn't up yet
after login or resume nothing was fetched until the next interval. Now
it is retried after 30 seconds, doubling the delay after each failure.

BUG: 507273
---
 applets/weather/forecastcontrol.cpp | 30 +++++++++++++++++++++++++++++
 applets/weather/forecastcontrol.h   |  2 ++
 2 files changed, 32 insertions(+)

diff --git a/applets/weather/forecastcontrol.cpp b/applets/weather/forecastcontrol.cpp
index 6cfbf4318..3387e7154 100644
--- a/applets/weather/forecastcontrol.cpp
+++ b/applets/weather/forecastcontrol.cpp
@@ -17,6 +17,7 @@ using namespace Qt::StringLiterals;

 inline constexpr QLatin1StringView LOGIN1_SERVICE("org.freedesktop.login1");
 inline constexpr QLatin1StringView CONSOLEKIT2_SERVICE("org.freedesktop.ConsoleKit");
+inline constexpr std::chrono::seconds FIRST_RETRY_INTERVAL(30);

 // Constructor
 ForecastControl::ForecastControl(QObject *parent)
@@ -30,6 +31,15 @@ ForecastControl::ForecastControl(QObject *parent)
         updateForecastInfo();
     });

+    // used to retry soon after a failed update, e.g. when the network isn't fully up yet after login or resume
+    m_retryTimer = new QTimer(this);
+    m_retryTimer->setSingleShot(true);
+    m_retryInterval = FIRST_RETRY_INTERVAL;
+    connect(m_retryTimer, &QTimer::timeout, this, [this]() {
+        qCDebug(WEATHER::CONTROLLER) << "ForecastControl: RetryTimer: retry updating forecast info";
+        updateForecastInfo();
+    });
+
     if (QDBusConnection::systemBus().interface()->isServiceRegistered(LOGIN1_SERVICE)) {
         m_login1Interface = std::make_unique<QDBusInterface>(LOGIN1_SERVICE,
                                                              u"/org/freedesktop/login1"_s,
@@ -83,6 +93,18 @@ void ForecastControl::onWeatherDataUpdated()
         qCDebug(WEATHER::CONTROLLER) << "ForecastControl: forecast data didn't updated due to error";
         m_status = Timeout;
         Q_EMIT forecastChanged();
+
+        if (!m_retryTimer->isActive()) {
+            if (m_updateTimer->interval() > 0) {
+                m_retryInterval = std::min(m_retryInterval, std::chrono::duration_cast<std::chrono::seconds>(m_updateTimer->intervalAsDuration()));
+            }
+            qCDebug(WEATHER::CONTROLLER) << "ForecastControl: retry update in" << m_retryInterval.count() << "seconds";
+            m_retryTimer->start(m_retryInterval);
+            m_retryInterval *= 2;
+        }
+    } else {
+        m_retryTimer->stop();
+        m_retryInterval = FIRST_RETRY_INTERVAL;
     }

     m_status = Normal;
@@ -126,6 +148,9 @@ bool ForecastControl::setForecastLocation(const QString &provider, const QString
         m_forecastData.reset();
     }

+    m_retryTimer->stop();
+    m_retryInterval = FIRST_RETRY_INTERVAL;
+
     if (provider.isEmpty() || place.isEmpty()) {
         m_status = NeedsConfiguration;
         return false;
@@ -187,6 +212,11 @@ bool ForecastControl::isDataOutdated() const
         return true;
     }

+    // a failed update doesn't count as fresh data
+    if (!m_forecastData->forecast() || m_forecastData->forecast()->isError()) {
+        return true;
+    }
+
     lastUpdate = lastUpdate.addMSecs(m_updateTimer->interval());

     return lastUpdate <= QDateTime::currentDateTime();
diff --git a/applets/weather/forecastcontrol.h b/applets/weather/forecastcontrol.h
index 9025b66ae..c7a6f9eba 100644
--- a/applets/weather/forecastcontrol.h
+++ b/applets/weather/forecastcontrol.h
@@ -91,6 +91,8 @@ private Q_SLOTS:

 private:
     QTimer *m_updateTimer;
+    QTimer *m_retryTimer;
+    std::chrono::seconds m_retryInterval;

     std::shared_ptr<ForecastData> m_forecastData;

